// 交割账按原接受累计扣额度，钱物只在一次Common recipe内移动，未结责任保持原人原约。
#include "family_inheritance.hpp"
#include <algorithm>
#include <charconv>
#include <limits>
#include <set>
namespace hanmo::resident {namespace {
// 原Common序是所有跨域来源的边界，未知事实不产生默许。
bool before(const CommonStore& c,const StableId& a,const StableId& b){const auto& ids=c.state().facts.order();auto x=std::find(ids.begin(),ids.end(),a),y=std::find(ids.begin(),ids.end(),b);return x!=ids.end()&&y!=ids.end()&&x<y;}
// 交割先分配本域事实，紧接每原批产生一个新lot；精确ID序不容挪用别次物资。
Outcome<Integer> sequence(const StableId& id){const StableId prefix="family_inheritance:";if(id.rfind(prefix,0)!=0)return {false,{},common_failure("InvalidInheritanceSettlementId").error};auto text=id.substr(prefix.size());Integer n=0;auto parsed=std::from_chars(text.data(),text.data()+text.size(),n);if(parsed.ec!=std::errc{}||parsed.ptr!=text.data()+text.size()||n<1||std::to_string(n)!=text)return {false,{},common_failure("InvalidInheritanceSettlementId").error};return {true,n,{}};}
}
// 只有原本人已接受的同一声明才形成额度；当前物资是否仍在由资产读再次检查。
Outcome<InheritancePersonalEntitlement> inheritance_personal_entitlement(const CommonStore& c,const FamilyBequestState& grants,const FamilyInheritanceState& state,const StableId& accepted,const StableId& boundary){const auto* a=state.acceptances.find(accepted);const auto* grant=a?grants.declarations.find(a->declaration_id):nullptr;if(!a||!grant)return {false,{},common_failure("InheritanceAcceptanceRequired").error};if(!boundary.empty()&&!c.state().facts.find(boundary))return {false,{},common_failure("InheritanceSettlementBoundaryRequired").error};const auto& t=grant->source.terms;InheritancePersonalEntitlement e;e.declaration_id=a->declaration_id;e.acceptance_fact_id=accepted;e.death_fact_id=a->death_fact_id;e.donor_actor_id=t.donor_actor_id;e.beneficiary_actor_id=t.beneficiary_actor_id;e.source_wallet_id=t.source_wallet_id;e.source_inventory_id=t.source_inventory_id;e.money_remaining=t.money;e.remaining_lots=t.lots;
    for(const auto& id:c.state().facts.order()){if(id==boundary)break;const auto* prior=state.settlements.find(id);if(!prior||prior->acceptance_fact_id!=accepted)continue;if(prior->transfer.money<0||prior->transfer.money>e.money_remaining)return {false,{},common_failure("InheritanceMoneyLimitExceeded",id).error};e.money_remaining-=prior->transfer.money;std::set<StableId> seen;for(const auto& p:prior->transfer.lots){auto original=std::find_if(e.remaining_lots.begin(),e.remaining_lots.end(),[&](const auto& l){return l.lot_id==p.lot_id;});if(original==e.remaining_lots.end()||original->item_id!=p.item_id||p.quantity<=0||p.quantity>original->quantity||!seen.insert(p.lot_id).second)return {false,{},common_failure("InheritanceOriginalLotLimitExceeded",id).error};original->quantity-=p.quantity;}}
    e.remaining_lots.erase(std::remove_if(e.remaining_lots.begin(),e.remaining_lots.end(),[](const auto& lot){return lot.quantity==0;}),e.remaining_lots.end());return {true,std::move(e),{}};
}
// 历史责任必须走真实before_fact证明，不能把当前债已付/状态已停当作过去一直免责。
Status validate_family_inheritance_settlements(const CommonStore& c,const FamilyBequestState& grants,const FamilyDeathState& life,const InteractionCatalog& catalog,const FamilyBequestPlayerRead& player,const FamilyInheritanceState& state,const InheritancePrivateClearanceRead& clearance,const FamilyInheritanceSources2* sources,Integer version){if(version!=1&&version!=2)return common_failure("FamilyInheritanceVersionRequired",{},ErrorKind::unsupported_capability);if(version==2&&(!sources||!sources->bound_to(c,life)))return common_failure("InheritanceCompleteSourcesRequired",{},ErrorKind::unsupported_capability);std::set<StableId> new_lots;
    for(const auto& row:state.settlements.rows()){const auto& f=row.second;auto remaining=inheritance_personal_entitlement(c,grants,state,f.acceptance_fact_id,row.first);if(!remaining.ok)return {false,{},remaining.error};const auto& e=remaining.value;const auto* accepted=state.acceptances.find(f.acceptance_fact_id);const auto* death=life.deaths.find(e.death_fact_id);if(f.kind!="family_inheritance_settled"||!accepted||!death||!before(c,f.acceptance_fact_id,row.first)||f.tick<accepted->tick||(version==1&&f.tick>c.tick())||f.transfer.money<0||f.transfer.money>e.money_remaining||(f.transfer.money==0&&f.transfer.lots.empty()))return common_failure("InvalidInheritanceSettlement",row.first);if(version==2){auto actual=validate_inheritance_exact_moment(*sources,f.tick,f.occurred_at);if(!actual.ok)return actual;if(!accepted->occurred_at)return common_failure("InheritanceAcceptanceExactSourceRequired",{},ErrorKind::internal);auto order=compare_world_moments(*accepted->occurred_at,*f.occurred_at);if(!order.ok)return {false,{},order.error};if(order.value>0)return common_failure("InheritanceSettlementBeforeAcceptance");const SourceRef cut{"family_inheritance",f.kind,row.first};actual=sources->validate_original_physical_contact(e.donor_actor_id,e.beneficiary_actor_id,f.place_id,f.settlement_id,*f.occurred_at,&cut);if(!actual.ok)return actual;auto presence=sources->people().read_presence_before_original_fact(e.beneficiary_actor_id,f.tick,cut);if(!presence.ok)return {false,{},presence.error};if(!presence.value.alive)return common_failure("InheritanceSettlementAfterDeath");}else if(f.occurred_at||accepted->occurred_at)return common_failure("InheritanceProfileMismatch",{},ErrorKind::internal);const auto& t=f.transfer;auto shape=validate_succession_personal_terms(t);if(!shape.ok)return shape;
        if(t.predecessor_actor_id!=e.donor_actor_id||t.successor_actor_id!=e.beneficiary_actor_id||t.source_wallet_id!=e.source_wallet_id||t.source_inventory_id!=e.source_inventory_id)return common_failure("InheritanceSettlementScopeMismatch",row.first);const auto* donor=c.actor(e.donor_actor_id);const auto* recipient=c.actor(e.beneficiary_actor_id);const auto* location=donor?std::get_if<SettlementLocation>(&donor->location):nullptr;const auto* place=catalog.common?catalog.common->places.find(f.place_id):nullptr;if(!recipient||recipient->wallet_id!=t.destination_wallet_id||recipient->inventory_id!=t.destination_inventory_id||(version==1&&(!location||location->place_id!=f.place_id||location->settlement_id!=f.settlement_id))||!place||place->settlement_id!=f.settlement_id)return common_failure("InheritanceSettlementPhysicalSourceMismatch",row.first);
        if(f.source_balance_before<t.money||f.destination_balance_before<0||f.destination_balance_before>std::numeric_limits<Integer>::max()-t.money||f.destination_lot_ids.size()!=t.lots.size())return common_failure("InheritanceSettlementAssetMismatch",row.first);auto seq=sequence(row.first);if(!seq.ok)return {false,{},seq.error};if(seq.value>=c.state().next_instance_id||seq.value>std::numeric_limits<Integer>::max()-static_cast<Integer>(t.lots.size()))return common_failure("InheritanceSettlementInstanceMismatch");
        for(std::size_t i=0;i<t.lots.size();++i){const auto& lot=t.lots[i];auto limit=std::find_if(e.remaining_lots.begin(),e.remaining_lots.end(),[&](const auto& old){return old.lot_id==lot.lot_id;});if(limit==e.remaining_lots.end()||limit->item_id!=lot.item_id||lot.quantity>limit->quantity||f.destination_lot_ids[i]!="lot:"+std::to_string(seq.value+1+static_cast<Integer>(i))||seq.value+1+static_cast<Integer>(i)>=c.state().next_instance_id||!new_lots.insert(f.destination_lot_ids[i]).second)return common_failure("InheritanceSettlementLotMismatch",row.first);}
        if(!player)return common_failure("InheritanceHistoricalPlayerRequired");auto who=player(f.tick,row.first);if(!who.ok)return {false,{},who.error};if(who.value!=e.beneficiary_actor_id)return common_failure("InheritanceBeneficiaryDecisionRequired");if(version==1){const auto* later=family_death_for_actor(life,e.beneficiary_actor_id);if(later&&(f.tick>later->death_tick||!before(c,row.first,later->cause_fact_id)))return common_failure("InheritanceSettlementAfterDeath");}if(!clearance)return common_failure("InheritanceResponsibilityHistoryUnavailable");auto free=clearance(e.donor_actor_id,e.source_wallet_id,e.source_inventory_id,f.tick,row.first);if(!free.ok)return free;
    }return common_success();
}
// 所有原账与通知先重验，再从真实累计账派生剩余额度，外部选择不能自带资产授权。
Outcome<InheritancePersonalQuote> preview_family_inheritance_settlement(const CommonStore& c,const FamilyBequestState& grants,const FamilyDeathState& life,const InteractionCatalog& catalog,const FamilyBequestPlayerRead& player,const FamilyReceivedDeathNoticeRead& notice,const FamilyInheritancePolicy& policy,const FamilyInheritanceState& state,const StableId& accepted,const InheritancePersonalSelection& selected,const InheritancePrivateClearanceRead& clearance,const FamilyInheritanceSources2* sources){if(!policy.enabled)return {false,{},common_failure("FamilyInheritanceProfileRequired").error};auto valid=validate_family_inheritance(c,grants,life,catalog,player,notice,policy,state,clearance,sources);if(!valid.ok)return {false,{},valid.error};auto source=inheritance_personal_entitlement(c,grants,state,accepted);if(!source.ok)return {false,{},source.error};auto quote=preview_inheritance_personal_assets(c,source.value,selected,clearance);if(!quote.ok)return quote;if(policy.selected_version==2){if(!sources)return {false,{},common_failure("InheritanceCompleteSourcesRequired",{},ErrorKind::unsupported_capability).error};auto now=sources->current_moment();if(!now.ok)return {false,{},now.error};auto physical=sources->validate_original_physical_contact(source.value.donor_actor_id,source.value.beneficiary_actor_id,quote.value.place_id,quote.value.settlement_id,now.value);if(!physical.ok)return {false,{},physical.error};}return quote;}
// 资源和事实均属于一个保存点，包含实际AddLot之后的历史责任/通知后验失败。
Outcome<StableId> settle_family_inheritance(CommonStore& c,const FamilyBequestState& grants,const FamilyDeathState& life,const InteractionCatalog& catalog,const FamilyBequestPlayerRead& player,const FamilyReceivedDeathNoticeRead& notice,const FamilyInheritancePolicy& policy,FamilyInheritanceState& state,const InheritancePersonalQuote& quote,const InheritancePrivateClearanceRead& clearance,const FamilyInheritanceSources2* sources){auto fresh=preview_family_inheritance_settlement(c,grants,life,catalog,player,notice,policy,state,quote.entitlement.acceptance_fact_id,quote.selected,clearance,sources);if(!fresh.ok)return {false,{},fresh.error};std::optional<WorldMoment> actual_at;if(policy.selected_version==2){if(!sources)return {false,{},common_failure("InheritanceCompleteSourcesRequired",{},ErrorKind::unsupported_capability).error};auto at=sources->current_moment();if(!at.ok)return {false,{},at.error};actual_at=std::move(at.value);}auto recipe=inheritance_personal_asset_recipe(c,fresh.value.entitlement,quote,clearance);if(!recipe.ok)return {false,{},recipe.error};auto mark=c.begin_savepoint();if(!mark.ok)return {false,{},mark.error};auto next=state;auto abort=[&](Status error)->Outcome<StableId>{auto rolled=c.rollback_savepoint(mark.value);return {false,{},rolled.ok?error.error:rolled.error};};auto id=c.next_id("family_inheritance");if(!id.ok)return abort({false,{},id.error});auto valid=c.apply_resources(recipe.value);if(!valid.ok)return abort(valid);FamilyInheritanceSettlement f;f.acceptance_fact_id=quote.entitlement.acceptance_fact_id;f.transfer=quote.transfer;f.occurred_at=std::move(actual_at);f.tick=f.occurred_at?f.occurred_at->half_day_tick:c.tick();f.place_id=quote.place_id;f.settlement_id=quote.settlement_id;f.source_balance_before=quote.source_balance;f.destination_balance_before=quote.destination_balance;auto seq=sequence(id.value);if(!seq.ok)return abort({false,{},seq.error});const auto* destination=c.inventory(f.transfer.destination_inventory_id);for(std::size_t i=0;i<f.transfer.lots.size();++i){const auto name="lot:"+std::to_string(seq.value+1+static_cast<Integer>(i));auto actual=std::find_if(destination->lots.begin(),destination->lots.end(),[&](const auto& lot){return lot.id==name;});const auto& old=f.transfer.lots[i];if(actual==destination->lots.end()||actual->item_id!=old.item_id||actual->quantity!=old.quantity||actual->owner.kind!=Owner::Kind::actor||actual->owner.id!=f.transfer.successor_actor_id||actual->owner.extra||actual->reserved_by!=ReservationRef{})return abort(common_failure("InheritanceNewLotMismatch",name));f.destination_lot_ids.push_back(name);}if(!next.settlements.insert(id.value,f))return abort(common_failure("DuplicateInheritanceSettlement"));valid=c.append_fact({id.value,f.kind,"family_inheritance"});if(!valid.ok)return abort(valid);valid=validate_family_inheritance(c,grants,life,catalog,player,notice,policy,next,clearance,sources);if(!valid.ok)return abort(valid);valid=c.commit_savepoint(mark.value);if(!valid.ok)return {false,{},valid.error};state=std::move(next);return {true,id.value,{}};}
}
